from llm_saea import Plan, benchmark, optimize

PLAN = Plan.from_dict({'surrogate': 'auto', 'operator': 'best1', 'mutation': 0.9, 'crossover': 0.7, 'exploration': 0.6, 'local_fraction': 0.45, 'radius': 0.2, 'population': 30, 'generations': 8, 'reason': 'With 5D, 24/100 evals used and long stagnation (19) with zero recent improvement, the search is likely over-exploiting. Auto surrogate keeps RBF/quadratic flexibility while data is still sparse. best1 drives toward the incumbent best to escape stagnation, and I raise exploration to 0.6 and local_fraction/radius moderately so the acquisition prunes toward novel regions rather than over-crowding near one optimum. Population 30 with 8 generations fits the remaining budget and keeps surrogate refits cheap.'})

def solve(problem, budget=100, seed=0):
    return optimize(problem, budget=budget, seed=seed, method='saea', plan=PLAN)

if __name__ == '__main__':
    result = solve(benchmark('sphere', 5))
    print({'best_y': result.best_y, 'best_x': result.best_x.tolist()})
